const queryClient = new QueryClient();
type Step = 'about' | 'vehicle' | 'drivers' | 'coverage' | 'loading' | 'results' | 'compare' | 'details' | 'customer' | 'payment' | 'confirmation';
const progressSteps = ['About You', 'Vehicle', 'Drivers', 'Coverage', 'Your Options'];

const fieldClass = 'w-full rounded-xl border border-input bg-card px-4 py-3 text-[15px] outline-none transition focus:border-ring focus:ring-4 focus:ring-ring/10';
const primaryButton = 'inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3.5 text-sm font-bold text-primary-foreground transition hover:-translate-y-0.5 hover:shadow-lg hover:shadow-primary/15 disabled:cursor-not-allowed disabled:opacity-50';
const quietButton = 'inline-flex items-center justify-center gap-2 rounded-xl border border-border bg-card px-5 py-3.5 text-sm font-bold text-foreground transition hover:border-ring hover:bg-secondary';

function Brand({ light = false }: { light?: boolean }) {
  return <Link href="/" className={`group flex items-center gap-2.5 ${light ? 'text-primary-foreground' : 'text-foreground'}`} data-testid="link-brand">
    <span className="grid h-9 w-9 place-items-center rounded-[11px] bg-accent text-primary"><ArrowRight size={19} strokeWidth={3} /></span>
    <span className="display text-lg font-extrabold tracking-[-.04em]">uplift<span className="text-accent">.</span></span>
  </Link>;
}

function Field({ label, id, value, onChange, type = 'text', placeholder, hint, required = true }: {
  label: string; id: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string; hint?: string; required?: boolean;
}) {
  return <label className="block space-y-2">
    <span className="flex items-center gap-1.5 text-sm font-semibold">{label}{required && <span className="text-destructive">*</span>}</span>
    <input data-testid={`input-${id}`} className={fieldClass} type={type} value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} />
    {hint && <span className="block text-xs text-muted-foreground">{hint}</span>}
  </label>;
}

function SelectField({ label, id, value, onChange, options }: { label: string; id: string; value: string; onChange: (v: string) => void; options: string[] }) {
  return <label className="block space-y-2"><span className="text-sm font-semibold">{label}</span>
    <span className="relative block"><select data-testid={`select-${id}`} className={`${fieldClass} appearance-none pr-10`} value={value} onChange={(e) => onChange(e.target.value)}>{options.map((option) => <option key={option}>{option}</option>)}</select><ChevronDown className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground" size={17} /></span>
  </label>;
}

function OptionCard({ selected, label, detail, onClick, testId }: { selected: boolean; label: string; detail?: string; onClick: () => void; testId: string }) {
  return <button data-testid={testId} onClick={onClick} className={`relative w-full rounded-xl border p-4 text-left transition ${selected ? 'border-ring bg-secondary accent-ring' : 'border-border bg-card hover:border-ring/60'}`}>
    <span className={`absolute right-3 top-3 grid h-5 w-5 place-items-center rounded-full border ${selected ? 'border-primary bg-primary text-primary-foreground' : 'border-muted-foreground/40'}`}>{selected && <Check size={13} strokeWidth={3} />}</span>
    <span className="block pr-7 text-sm font-bold">{label}</span>{detail && <span className="mt-1 block text-xs text-muted-foreground">{detail}</span>}
  </button>;
}

function Header({ onMenu }: { onMenu?: () => void }) {
  return <header className="border-b border-border/80 bg-background/90 backdrop-blur-xl">
    <div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-4 lg:px-8">
      <Brand />
      <div className="hidden items-center gap-6 text-sm font-semibold text-muted-foreground sm:flex"><span className="flex items-center gap-2"><LockKeyhole size={14} /> Your information is secure</span><span>Questions? <a data-testid="link-support" href="tel:8005550144" className="text-foreground underline underline-offset-4">800 555 0144</a></span></div>
      {onMenu && <button data-testid="button-mobile-menu" onClick={onMenu} className="rounded-lg p-2 sm:hidden"><Menu size={21} /></button>}
    </div>
  </header>;
}

